// swift-tools-version: 6.0
// LibarrieKit: API client, sign-in, image preparation and the durable
// capture/upload queue. LibarrieUI: SwiftUI screens. Both build for iOS and
// (for type-checking and tests without Xcode) macOS. The iOS app target
// lives in App/ and is generated by XcodeGen from project.yml.
// No third-party dependencies: Apple frameworks only.
import PackageDescription

let package = Package(
    name: "Libarrie",
    platforms: [.iOS(.v17), .macOS(.v14)],
    products: [
        .library(name: "LibarrieKit", targets: ["LibarrieKit"]),
        .library(name: "LibarrieUI", targets: ["LibarrieUI"]),
    ],
    targets: [
        .target(name: "LibarrieKit"),
        .target(name: "LibarrieUI", dependencies: ["LibarrieKit"]),
        // Tests read the server-generated fixtures in contracts/fixtures/api.
        .testTarget(name: "LibarrieKitTests", dependencies: ["LibarrieKit"]),
        .testTarget(name: "LibarrieUITests", dependencies: ["LibarrieUI", "LibarrieKit"]),
    ]
)
